38	
39	/**
40	 * NutritionController — Deliverable 1 §5.2 "Controllers": submitMealPhoto(image) : MealEntry,
41	 * getMenu(location) : List&lt;DiningItem&gt;, saveMealEntry(entry), saveWaterEntry(volumeMl). Uses AIFoodService
42	 * and DiningMenuService. Follows SD-1 "Track Nutrition and Hydration (UC-1)".
43	 * FR-2 (calories), FR-6 (water), FR-8 (UTD Dining nutrition info). §5.3.2 "Nutrition Service: meals, water,
44	 * dining menu". The whole controller is the NUTRITION module (FR-5).
45	 */
46	@RestController
47	@RequestMapping("/api/nutrition")
48	public class NutritionController extends BaseController {
49	    private final AIFoodService aiFoodService;
50	    private final DiningMenuService diningMenuService;
51	    private final DailySummaryService summaries;
52	    private final MealEntryRepository meals;
53	    private final WaterEntryRepository water;
54	    private final DiningItemRepository diningItems;
55	    private final Clock clock;
56	
57	    public NutritionController(AuthService authService, AIFoodService aiFoodService, DiningMenuService diningMenuService,
58	                               DailySummaryService summaries, MealEntryRepository meals, WaterEntryRepository water,
59	                               DiningItemRepository diningItems, Clock clock) {
60	        super(authService);
61	        this.aiFoodService = aiFoodService;
62	        this.diningMenuService = diningMenuService;
63	        this.summaries = summaries;
64	        this.meals = meals;
65	        this.water = water;
66	        this.diningItems = diningItems;
67	        this.clock = clock;
68	    }
69	
70	    /** Body of saveMealEntry(entry). For DINING_MENU entries the macros are taken from the DiningItem. */
71	    public record MealEntryRequest(@Size(max = 120) String foodName,
72	                                   @Min(0) @Max(5000) Integer calories,
73	                                   @DecimalMin("0") @DecimalMax("1000") Double proteinG,
74	                                   @DecimalMin("0") @DecimalMax("1000") Double carbsG,
75	                                   @DecimalMin("0") @DecimalMax("1000") Double fatG,
76	                                   @NotNull MealSource source,
77	                                   Long diningItemId) {}
78	
79	    public record WaterRequest(@NotNull @Min(1) @Max(5000) Integer volumeMl) {}
80	
81	    /** "show estimate for review" (SD-1): the unsaved MealEntry draft plus the individual recognised foods. */
82	    public record PhotoEstimate(MealEntryView draft, List<FoodEstimate> foodItems, String notice) {}
83	
84	    public record MealEntryView(Long entryId, String foodName, int calories, double proteinG, double carbsG,
85	                                double fatG, MealSource source, Long diningItemId, Instant loggedAt) {
86	        static MealEntryView of(MealEntry e) {
87	            return new MealEntryView(e.getEntryId(), e.getFoodName(), e.getCalories(), e.getProteinG(), e.getCarbsG(),
88	                    e.getFatG(), e.getSource(), e.getDiningItemId(), e.getLoggedAt());
89	        }
90	    }
91	
92	    public record SaveResult<T>(T saved, DailySummary summary) {}
93	
94	    // ---- alt [Photo entry] -------------------------------------------------------------------------------
95	
96	    /**
97	     * submitMealPhoto(image) : MealEntry — SD-1 "submitMealPhoto(image) -> estimateMacros(image) -> show estimate
