21	 * updated daily summary / display calories, macros, water progress". UC-1 "View Daily Summary &amp; Goals".
22	 * Steps are included because Student holds stepGoal and UC-2 syncs steps (FR-4).
23	 * FR-6 verification (RTM §4.4): "if the amount of water drank is too low, it will display a message" (A-19).
24	 */
25	@Service
26	public class DailySummaryService {
27	    private final MealEntryRepository meals;
28	    private final WaterEntryRepository water;
29	    private final ActivityRecordRepository activity;
30	    private final Clock clock;
31	
32	    public DailySummaryService(MealEntryRepository meals, WaterEntryRepository water,
33	                               ActivityRecordRepository activity, Clock clock) {
34	        this.meals = meals;
35	        this.water = water;
36	        this.activity = activity;
37	        this.clock = clock;
38	    }
39	
40	    public record DailySummary(LocalDate date, int calories, int calorieGoal, double proteinG, double carbsG,
41	                               double fatG, int waterMl, int waterGoalMl, int bottleSizeMl, int steps, int stepGoal,
42	                               Integer latestHeartRate, int mealCount, int waterEntryCount, List<String> messages) {}
43	
44	    @Transactional(readOnly = true)
45	    public DailySummary getDailySummary(Student s, LocalDate date) {
46	        Instant from = clock.startOf(date), to = clock.endOf(date);
47	        List<MealEntry> m = meals.findByStudentIdAndLoggedAtBetweenOrderByLoggedAtDesc(s.getUserId(), from, to);
48	        List<WaterEntry> w = water.findByStudentIdAndLoggedAtBetweenOrderByLoggedAtDesc(s.getUserId(), from, to);
49	        List<ActivityRecord> a = activity.findByStudentIdAndTimestampBetweenOrderByTimestampDesc(s.getUserId(), from, to);
50	
51	        int cal = m.stream().mapToInt(MealEntry::getCalories).sum();
52	        double p = round1(m.stream().mapToDouble(MealEntry::getProteinG).sum());
53	        double c = round1(m.stream().mapToDouble(MealEntry::getCarbsG).sum());
54	        double f = round1(m.stream().mapToDouble(MealEntry::getFatG).sum());
55	        int ml = w.stream().mapToInt(WaterEntry::getVolumeMl).sum();
56	        int steps = a.stream().mapToInt(ActivityRecord::getSteps).sum();
57	        Integer hr = a.stream().filter(r -> r.getHeartRate() != null).findFirst().map(ActivityRecord::getHeartRate).orElse(null);
58	
59	        List<String> msgs = new ArrayList<>();
60	        if (ml < s.getWaterGoalMl()) {
61	            msgs.add("Your water intake is low: " + ml + " of " + s.getWaterGoalMl()
62	                    + " ml today. Drink some water to stay hydrated.");
63	        } else {
64	            msgs.add("Water goal reached. Nice work staying hydrated!");
65	        }
66	        if (cal > s.getCalorieGoal()) {
67	            msgs.add("You are " + (cal - s.getCalorieGoal()) + " kcal over your calorie goal today.");
68	        }
69	        msgs.addAll(Student.safetyWarnings(s.getCalorieGoal(), s.getWaterGoalMl(), s.getStepGoal()));
70	
71	        return new DailySummary(date, cal, s.getCalorieGoal(), p, c, f, ml, s.getWaterGoalMl(), s.getBottleSizeMl(),
72	                steps, s.getStepGoal(), hr, m.size(), w.size(), msgs);
73	    }
74	
75	    private static double round1(double v) { return Math.round(v * 10) / 10.0; }
