1	// UC-1 Track Nutrition & Hydration — SD-1, all three alt branches plus water:
2	//   [Photo entry]       take photo -> submitMealPhoto(image) -> show estimate for review -> confirm / edit
3	//   [Dining menu item]  browse dining menu -> getMenu(location) -> menu list -> select item   (FR-8)
4	//   [Manual entry]      enter food name and calories                                           (FR-2)
5	//   then saveMealEntry(entry); "log water (bottle size / refill)" -> saveWaterEntry(volume)    (FR-6)
6	import * as ImagePicker from 'expo-image-picker';
7	import React, { useState } from 'react';
8	import { Platform, ScrollView, Text, View } from 'react-native';
9	import { api, ApiError } from '../api';
10	import { parseMacro, parsePositiveInt, progress, refillVolume, shortTime } from '../logic';
11	import type { DailySummary, DiningItem, MealSource, PhotoEstimate } from '../types';
12	import { Banner, Button, Card, colors, Field, MaintenanceNotice, ProgressBar, Row, s } from '../ui';
13	import { useAsync } from '../useAsync';
14	
15	type Mode = 'MANUAL' | 'PHOTO' | 'DINING_MENU';
16	
17	export default function LogScreen({ onChanged }: { onChanged: () => void }) {
18	  const summaryQ = useAsync(() => api.summary(), []);
19	  const mealsQ = useAsync(() => api.meals(), []);
20	  const [mode, setMode] = useState<Mode>('MANUAL');
21	  const [msg, setMsg] = useState<{ kind: 'good' | 'error'; text: string } | null>(null);
22	
23	  if (summaryQ.error?.isMaintenance) return <MaintenanceNotice name="Nutrition & Hydration" />;
24	
25	  function saved(summary: DailySummary, text: string) {
26	    summaryQ.setData(summary);
27	    mealsQ.reload();
28	    setMsg({ kind: 'good', text });
29	    onChanged();
30	  }
31	  function failed(e: unknown) {
32	    setMsg({ kind: 'error', text: (e as ApiError).message });
33	  }
34	
35	  const sum = summaryQ.data;
36	  return (
37	    <ScrollView>
38	      {msg ? <Banner kind={msg.kind}>{msg.text}</Banner> : null}
39	      <WaterCard summary={sum} onSaved={saved} onError={failed} />
40	
41	      <Card title="Log a meal">
42	        <Row>
43	          {(['MANUAL', 'PHOTO', 'DINING_MENU'] as Mode[]).map((m) => (
44	            <View key={m} style={{ flex: 1, minWidth: 100 }}>
45	              <Button
46	                kind={mode === m ? 'primary' : 'secondary'}
47	                label={m === 'MANUAL' ? 'Manual' : m === 'PHOTO' ? 'Photo (AI)' : 'Dining menu'}
48	                onPress={() => setMode(m)}
49	              />
50	            </View>
51	          ))}
52	        </Row>
53	        {mode === 'MANUAL' ? <ManualMeal source="MANUAL" onSaved={saved} onError={failed} /> : null}
54	        {mode === 'PHOTO' ? <PhotoMeal onSaved={saved} onError={failed} /> : null}
55	        {mode === 'DINING_MENU' ? <DiningMenu onSaved={saved} onError={failed} /> : null}
56	      </Card>
57	
58	      <Card title="Today's meals">
59	        {sum ? (
60	          <Text style={s.muted}>
61	            {sum.calories} / {sum.calorieGoal} kcal · P {sum.proteinG} g · C {sum.carbsG} g · F {sum.fatG} g
62	          </Text>
63	        ) : null}
64	        {(mealsQ.data ?? []).length === 0 ? <Text style={s.muted}>No meals logged yet today.</Text> : null}
65	        {(mealsQ.data ?? []).map((m) => (
66	          <View key={m.entryId ?? m.loggedAt} style={s.listItem}>
67	            <Text style={s.body}>
68	              {m.foodName} — {m.calories} kcal
69	            </Text>
70	            <Text style={s.muted}>
71	              {sourceLabel(m.source)} · P {m.proteinG} g · C {m.carbsG} g · F {m.fatG} g · {shortTime(m.loggedAt)}
72	            </Text>
73	          </View>
74	        ))}
75	      </Card>
76	    </ScrollView>
77	  );
78	}
79	
80	function sourceLabel(src: MealSource) {
81	  return src === 'PHOTO' ? 'Photo' : src === 'DINING_MENU' ? 'UTD Dining' : 'Manual';
82	}
83	
84	type SavedFn = (s: DailySummary, text: string) => void;
85	type ErrFn = (e: unknown) => void;
86	
87	// ---- FR-6 water -----------------------------------------------------------------------------------------------
88	function WaterCard({ summary, onSaved, onError }: { summary: DailySummary | null; onSaved: SavedFn; onError: ErrFn }) {
89	  const [custom, setCustom] = useState('');
90	  const [busy, setBusy] = useState(false);
91	  const bottle = summary?.bottleSizeMl ?? 500;
92	
93	  async function log(volumeMl: number) {
94	    setBusy(true);
95	    try {
96	      const r = await api.saveWaterEntry(volumeMl);
97	      onSaved(r.summary, `Logged ${volumeMl} ml of water.`);
98	      setCustom('');
99	    } catch (e) {
100	      onError(e);
101	    } finally {
102	      setBusy(false);
103	    }
104	  }
105	  const customMl = parsePositiveInt(custom, 5000);
106	  return (
107	    <Card title="Water">
108	      {summary ? (
109	        <>
110	          <Text style={s.body}>
111	            {summary.waterMl} / {summary.waterGoalMl} ml today
112	          </Text>
113	          <ProgressBar value={progress(summary.waterMl, summary.waterGoalMl)} color="#2A8BD8" />
114	          {summary.waterMl < summary.waterGoalMl ? (
115	            <Banner kind="warn">Your water intake is low today. Refill your bottle!</Banner>
116	          ) : null}
117	        </>
118	      ) : null}
119	      <Row>
120	        <View style={{ flex: 1 }}>
121	          <Button label={`+1 refill (${bottle} ml)`} onPress={() => log(refillVolume(bottle, 1))} busy={busy} testID="refill" />
122	        </View>
123	        <View style={{ flex: 1 }}>
124	          <Button kind="secondary" label={`+½ bottle (${refillVolume(bottle, 0.5)} ml)`} onPress={() => log(refillVolume(bottle, 0.5))} disabled={busy} />
125	        </View>
126	      </Row>
127	      <Row>
128	        <View style={{ flex: 2 }}>
129	          <Field label="Other amount (ml)" value={custom} onChangeText={setCustom} keyboardType="number-pad" />
130	        </View>
131	        <View style={{ flex: 1 }}>
132	          <Button label="Add" onPress={() => customMl && log(customMl)} disabled={!customMl || busy} />
133	        </View>
134	      </Row>
135	      <Text style={s.muted}>Bottle size can be changed in Profile → Goals.</Text>
136	    </Card>
137	  );
138	}
139	
140	// ---- [Manual entry] (also used to confirm / edit a photo estimate) ---------------------------------------------
141	function ManualMeal({
142	  source, initial, onSaved, onError, onDone,
143	}: {
144	  source: MealSource;
145	  initial?: { foodName: string; calories: number; proteinG: number; carbsG: number; fatG: number };
146	  onSaved: SavedFn;
147	  onError: ErrFn;
148	  onDone?: () => void;
149	}) {
150	  const [name, setName] = useState(initial?.foodName ?? '');
151	  const [cal, setCal] = useState(initial ? String(initial.calories) : '');
152	  const [p, setP] = useState(initial ? String(round1(initial.proteinG)) : '');
153	  const [c, setC] = useState(initial ? String(round1(initial.carbsG)) : '');
154	  const [f, setF] = useState(initial ? String(round1(initial.fatG)) : '');
155	  const [busy, setBusy] = useState(false);
156	
157	  const calories = cal.trim() === '0' ? 0 : parsePositiveInt(cal, 5000);
158	  const macros = [parseMacro(p), parseMacro(c), parseMacro(f)];
159	  const valid = name.trim().length > 0 && calories !== null && macros.every((x) => x !== null);
160	
161	  async function save() {
162	    setBusy(true);
163	    try {
164	      const r = await api.saveMealEntry({
165	        source, foodName: name.trim(), calories: calories!, proteinG: macros[0]!, carbsG: macros[1]!, fatG: macros[2]!,
166	      });
167	      onSaved(r.summary, `Saved "${r.saved.foodName}" (${r.saved.calories} kcal).`);
168	      setName(''); setCal(''); setP(''); setC(''); setF('');
169	      onDone?.();
170	    } catch (e) {
171	      onError(e);
172	    } finally {
173	      setBusy(false);
174	    }
175	  }
176	
177	  return (
178	    <View style={{ marginTop: 8 }}>
179	      <Field label="Food name" value={name} onChangeText={setName} testID="food-name" />
180	      <Field label="Calories (kcal)" value={cal} onChangeText={setCal} keyboardType="number-pad" testID="food-cal" />
181	      <Row>
182	        <View style={{ flex: 1 }}><Field label="Protein g" value={p} onChangeText={setP} keyboardType="decimal-pad" /></View>
183	        <View style={{ flex: 1 }}><Field label="Carbs g" value={c} onChangeText={setC} keyboardType="decimal-pad" /></View>
184	        <View style={{ flex: 1 }}><Field label="Fat g" value={f} onChangeText={setF} keyboardType="decimal-pad" /></View>
185	      </Row>
186	      <Button label={source === 'PHOTO' ? 'Confirm & save' : 'Save meal'} onPress={save} disabled={!valid} busy={busy} testID="save-meal" />
187	    </View>
188	  );
189	}
190	
191	function round1(n: number) {
192	  return Math.round(n * 10) / 10;
193	}
194	
195	// ---- [Photo entry] ---------------------------------------------------------------------------------------------
196	function PhotoMeal({ onSaved, onError }: { onSaved: SavedFn; onError: ErrFn }) {
197	  const [estimate, setEstimate] = useState<PhotoEstimate | null>(null);
198	  const [busy, setBusy] = useState(false);
199	
200	  async function pick(camera: boolean) {
201	    try {
