1	// CometFit mobile client (Expo / React Native; also runs in a browser for the demo — ASSUMPTIONS A-26).
2	// Deliverable 1 §5.3: client-server — this is the "Client (Mobile Application)"; every SD-1..SD-4 "Mobile App (View)"
3	// lifeline is one of the screens below. Developers get the "AdminDashboard (View)" of SD-4 instead.
4	import { StatusBar } from 'expo-status-bar';
5	import React, { useCallback, useEffect, useState } from 'react';
6	import { Pressable, SafeAreaView, StyleSheet, Text, View } from 'react-native';
7	import { api, setToken, setUnauthorizedHandler } from './src/api';
8	import { isEnabled } from './src/logic';
9	import ActivityScreen from './src/screens/ActivityScreen';
10	import AdminDashboard from './src/screens/AdminDashboard';
11	import FriendsScreen from './src/screens/FriendsScreen';
12	import LoginScreen from './src/screens/LoginScreen';
13	import LogScreen from './src/screens/LogScreen';
14	import ProfileScreen from './src/screens/ProfileScreen';
15	import TodayScreen from './src/screens/TodayScreen';
16	import type { LoginResponse, ModuleState } from './src/types';
17	import { colors, MaintenanceNotice } from './src/ui';
18	
19	type Tab = 'today' | 'log' | 'activity' | 'friends' | 'profile';
20	
21	const TABS: { id: Tab; label: string; module?: string; moduleName?: string }[] = [
22	  { id: 'today', label: 'Today', module: 'NUTRITION', moduleName: 'Nutrition & Hydration' },
23	  { id: 'log', label: 'Log', module: 'NUTRITION', moduleName: 'Nutrition & Hydration' },
24	  { id: 'activity', label: 'Activity', module: 'ACTIVITY', moduleName: 'Activity & UREC Visits' },
25	  { id: 'friends', label: 'Friends', module: 'SOCIAL', moduleName: 'Friends & Leaderboard' },
26	  { id: 'profile', label: 'Profile' },
27	];
28	
29	const MODULE_POLL_MS = 15_000;
30	
31	export default function App() {
32	  const [session, setSession] = useState<LoginResponse | null>(null);
33	
34	  const logout = useCallback(async () => {
35	    try {
36	      await api.logout();
37	    } catch {
38	      /* session may already be gone */
39	    }
40	    setToken(null);
41	    setSession(null);
42	  }, []);
43	
44	  useEffect(() => {
45	    setUnauthorizedHandler(() => {
46	      setToken(null);
47	      setSession(null);
48	    });
49	    return () => setUnauthorizedHandler(null);
50	  }, []);
51	
52	  function loggedIn(r: LoginResponse) {
53	    setToken(r.token);
54	    setSession(r);
55	  }
56	
57	  return (
58	    <SafeAreaView style={styles.root}>
59	      <StatusBar style="dark" />
60	      {!session ? (
61	        <LoginScreen onLoggedIn={loggedIn} />
62	      ) : session.user.role === 'DEVELOPER' ? (
63	        <AdminDashboard onLogout={logout} />
64	      ) : (
65	        <StudentApp session={session} onLogout={logout} />
66	      )}
67	    </SafeAreaView>
68	  );
69	}
70	
71	function StudentApp({ session, onLogout }: { session: LoginResponse; onLogout: () => void }) {
72	  const [tab, setTab] = useState<Tab>('today');
73	  const [modules, setModules] = useState<ModuleState[] | null>(null);
74	  const [refreshKey, setRefreshKey] = useState(0);
75	
76	  // SD-4: Mobile App (Student) -> FeatureFlagService isEnabled(moduleId)
77	  useEffect(() => {
78	    let alive = true;
79	    const load = () => api.modules().then((m) => alive && setModules(m)).catch(() => undefined);
80	    load();
81	    const t = setInterval(load, MODULE_POLL_MS);
82	    return () => {
83	      alive = false;
84	      clearInterval(t);
85	    };
86	  }, [tab]);
87	
88	  const current = TABS.find((t) => t.id === tab)!;
89	  const bump = () => setRefreshKey((k) => k + 1);
90	  const disabled = current.module && !isEnabled(modules, current.module);
91	
92	  return (
93	    <View style={styles.phone}>
94	      <View style={styles.header}>
95	        <Text style={styles.brand}>CometFit</Text>
96	        <Text style={styles.hello}>Hi, {session.user.displayName}</Text>
97	      </View>
98	      <View style={styles.content}>
99	        {disabled ? (
100	          <MaintenanceNotice name={current.moduleName!} />
101	        ) : tab === 'today' ? (
102	          <TodayScreen refreshKey={refreshKey} />
103	        ) : tab === 'log' ? (
104	          <LogScreen onChanged={bump} />
105	        ) : tab === 'activity' ? (
106	          <ActivityScreen onChanged={bump} />
107	        ) : tab === 'friends' ? (
108	          <FriendsScreen me={session.user.userId} />
109	        ) : (
110	          <ProfileScreen onLogout={onLogout} onChanged={bump} />
111	        )}
112	      </View>
113	      <View style={styles.tabs}>
114	        {TABS.map((t) => {
115	          const off = t.module && !isEnabled(modules, t.module);
116	          return (
117	            <Pressable key={t.id} onPress={() => setTab(t.id)} style={styles.tab} accessibilityRole="tab" testID={`tab-${t.id}`}>
118	              <Text style={[styles.tabText, tab === t.id && styles.tabActive, off ? styles.tabOff : null]}>
119	                {t.label}
120	                {off ? ' ⚠' : ''}
121	              </Text>
122	            </Pressable>
123	          );
124	        })}
125	      </View>
