1	// Client unit tests (run with `npm test`, Node's built-in runner with TypeScript type stripping).
2	import assert from 'node:assert/strict';
3	import { test } from 'node:test';
4	import { formatDuration, goalWarnings, isEnabled, parseMacro, parsePositiveInt, progress, refillVolume } from '../src/logic.ts';
5	import { FakeSmartDevice, seeded } from '../src/smartDevice.ts';
6	
7	// UC-1 "View Daily Summary & Goals"
8	test('progress is clamped to 0..1 and safe for a zero goal', () => {
9	  assert.equal(progress(500, 2000), 0.25);
10	  assert.equal(progress(3000, 2000), 1);
11	  assert.equal(progress(-1, 2000), 0);
12	  assert.equal(progress(10, 0), 0);
13	});
14	
15	// FR-6 / Proposal §4: water from bottle size x refills
16	test('refill volume uses the bottle size', () => {
17	  assert.equal(refillVolume(500, 1), 500);
18	  assert.equal(refillVolume(750, 0.5), 375);
19	  assert.equal(refillVolume(500, -2), 0);
20	  assert.equal(refillVolume(Number.NaN, 1), 0);
21	});
22	
23	// FR-5 / SD-4 isEnabled(moduleId)
24	test('module flags: disabled module is reported, unknown or not-yet-loaded count as enabled', () => {
25	  const mods = [
26	    { moduleId: 'SOCIAL', name: 'Friends', enabled: false },
27	    { moduleId: 'NUTRITION', name: 'Nutrition', enabled: true },
28	  ];
29	  assert.equal(isEnabled(mods, 'SOCIAL'), false);
30	  assert.equal(isEnabled(mods, 'NUTRITION'), true);
31	  assert.equal(isEnabled(mods, 'ACTIVITY'), true);
32	  assert.equal(isEnabled(null, 'SOCIAL'), true);
33	});
34	
35	// NFR Safety — client mirror of the server thresholds
36	test('unsafe goals produce warnings, safe goals none', () => {
37	  assert.deepEqual(goalWarnings(2000, 2000, 10000), []);
38	  assert.equal(goalWarnings(1000, 2000, 10000).length, 1);
39	  assert.match(goalWarnings(2000, 5000, 10000)[0], /excessive water/);
40	  assert.equal(goalWarnings(5000, 500, 40000).length, 3);
41	});
42	
43	test('number parsing for form fields', () => {
44	  assert.equal(parsePositiveInt('250'), 250);
45	  assert.equal(parsePositiveInt(' 12 '), 12);
46	  assert.equal(parsePositiveInt('0'), null);
47	  assert.equal(parsePositiveInt('12.5'), null);
48	  assert.equal(parsePositiveInt('6000', 5000), null);
49	  assert.equal(parseMacro(''), 0);
50	  assert.equal(parseMacro('12.5'), 12.5);
51	  assert.equal(parseMacro('-1'), null);
52	  assert.equal(parseMacro('abc'), null);
53	});
54	
55	test('durations are human readable', () => {
56	  assert.equal(formatDuration(42), '42s');
57	  assert.equal(formatDuration(125), '2m 5s');
58	  assert.equal(formatDuration(3720), '1h 2m');
59	});
60	
61	// FR-4 / SD-2: the stub smart device produces plausible, repeatable readings
62	test('FakeSmartDevice readings are plausible and deterministic per seed', () => {
